INSERT INTO tb_policy (name, product_feature_id, description, online_policy_body, policy_type, hash, modified_time, offline_policy_body, use_offline_policy, ppolicy_id, is_updated, manager_group_id) values
('Agent factory policy', 'AGENT_MGMT', 'Agent factory policy',
'','FACTORY', '0000000000', CURRENT_TIMESTAMP, NULL, NULL, NULL, false, NULL);
ELSE update tb_policy set online_policy_body =
'',modified_time = CURRENT_TIMESTAMP where product_feature_id = 'AGENT_MGMT' and policy_type = 'FACTORY'; END IF;

